const OUTPUT_PATH = "/output/entry.png";

function main(): void {
  const bytes = Buffer.from(MAP_JPEG_BASE64, "base64");
  mkdirSync(dirname(OUTPUT_PATH), { recursive: true });
  writeFileSync(OUTPUT_PATH, bytes);
  // Validation gate: re-read what was written and verify it is a whole
  // JPEG within the 1 MiB limit before reporting success.
  const written = readFileSync(OUTPUT_PATH);
  if (written.length > 1048576) {
    throw new Error(`entry.png too large: ${written.length} bytes (max 1048576)`);
  }
  if (written.length < 4 || written[0] !== 0xff || written[1] !== 0xd8 || written[2] !== 0xff) {
    throw new Error("entry.png is not a JPEG (missing FFD8FF SOI marker)");
  }
  if (written[written.length - 2] !== 0xff || written[written.length - 1] !== 0xd9) {
    throw new Error("entry.png is not a whole JPEG (missing FFD9 EOI marker)");
  }
  console.log(`wrote ${OUTPUT_PATH} (${bytes.length} bytes, 1024x1024 JPEG)`);
}

main();
